#!/bin/bash
# usage: tools_build_native.sh PKG [OUT]   e.g. tools_build_native.sh N13
# Builds a native data package CS31aData/<PKG> (generated by tools_gen_n13.py) in the project root: the library with lake,
# then every data module DIRECTLY with `lean -o` and the CS31aCert dynlibs (Lake's C emission of the big literals does not
# finish): the part modules (L/T/V), the assembly module, the shares C<j> (native_decide, all cores) and Main<PKG> if the
# shares cover all rows. Oleans go to OUT (default .lake/build/lib/lean); the axioms of Main<PKG> are printed at the end.
set -eu
PKG=$1
D=.lake/build/lib/lean; OUT=${2:-$D}
lake build CS31aCert.Bytes:dynlib CS31aCert.Step:dynlib CS31aCert.Row:dynlib CS31aCert.KTree:dynlib CS31aCert.Check:dynlib \
  CS31aCert.KStep:dynlib CS31aCert.Check2:dynlib CS31aCert.Check13:dynlib CS31aData.Elab CS31a.CheckNative13 CS31a.Assemble \
  CS31a.Count CS31a.CoverExists
LP=$OUT:$(lake env printenv LEAN_PATH); LEAN=$(lake env which lean)
if [ "$OUT" != "$D" ]; then  # Lean takes a package root from the first LEAN_PATH entry that has it: link the lake-built Elab
  mkdir -p $OUT/CS31aData; for e in olean ilean; do ln -sf $PWD/$D/CS31aData/Elab.$e $OUT/CS31aData/Elab.$e; done
fi
DL=""; for m in Bytes Step Row KTree Check KStep Check2 Check13; do DL="$DL --load-dynlib=$D/CS31a_CS31aCert_$m.so"; done
b() {
  local O=$OUT/$(echo $1 | tr . /); mkdir -p $(dirname $O)
  LEAN_PATH=$LP $LEAN --threads=${2:-1} $DL $(echo $1 | tr . /).lean -o $O.olean -i $O.ilean
  echo "built $1"
}
for f in CS31aData/$PKG/[LTV][0-9]*.lean; do b CS31aData.$PKG.$(basename $f .lean); done
b CS31aData.$PKG
for f in CS31aData/$PKG/C[0-9]*.lean; do b CS31aData.$PKG.$(basename $f .lean) $(nproc); done
if [ -e CS31aData/Main$PKG.lean ]; then
  b CS31aData.Main$PKG
  T=$(grep -oE '^theorem [A-Za-z0-9_]+ : gamma2' CS31aData/Main$PKG.lean | awk '{print $2}')
  printf 'import CS31aData.Main%s\n#print axioms CS31aData.%s\n' $PKG $T > $OUT/Ax$PKG.lean
  LEAN_PATH=$LP $LEAN $OUT/Ax$PKG.lean
fi
